import { fireEvent, render, screen } from '@testing-library/react';
import { Component } from 'react';
import { expect, it, vi } from 'vitest';
import { TicketTable } from './Solution';

class TableBoundary extends Component<{ children: React.ReactNode; onCatch: (e: unknown) => void }, { err: unknown }> {
  state = { err: null as unknown };
  static getDerivedStateFromError(error: unknown) {
    return { err: error };
  }
  componentDidCatch(error: unknown) {
    this.props.onCatch(error);
  }
  render() {
    if (this.state.err !== null) {
      return <button data-testid="reset" onClick={() => this.setState({ err: null })}>table-failed</button>;
    }
    return this.props.children;
  }
}

const TICKETS = [
  { id: 't1', raw: { title: '退款', amount: 12 } },
  { id: 't2', raw: { title: '改签', amount: 30 } },
  { id: 't3', raw: { title: '发票', amount: 7 } },
];

function abortError() {
  const e = new Error('signal aborted');
  e.name = 'AbortError';
  return e;
}

it('无数据时渲染空态且不抛错', () => {
  const onCatch = vi.fn();
  render(
    <TableBoundary onCatch={onCatch}>
      <TicketTable tickets={[]} renderDetail={(row) => row.raw.title} />
    </TableBoundary>,
  );
  expect(screen.getByTestId('empty').textContent).toBe('暂无数据');
  expect(onCatch).not.toHaveBeenCalled();
});

it('单行脏数据只降级该行', () => {
  const onCatch = vi.fn();
  const onRowError = vi.fn();
  render(
    <TableBoundary onCatch={onCatch}>
      <TicketTable
        tickets={TICKETS}
        onRowError={onRowError}
        renderDetail={(row) => {
          if (row.id === 't2') throw new Error('bad payload');
          return row.raw.title;
        }}
      />
    </TableBoundary>,
  );
  expect(screen.getByTestId('cell-t1').textContent).toBe('退款');
  expect(screen.getByTestId('cell-t3').textContent).toBe('发票');
  expect(screen.getByTestId('row-error-t2').textContent).toBe('本行暂不可用');
  expect(document.querySelectorAll('[data-testid^="cell-"]').length).toBe(2);
  expect(onCatch).not.toHaveBeenCalled();
  expect(screen.getByTestId('summary').textContent).toBe('共 3 行');
});

it('重复渲染同一坏行只上报一次', () => {
  const onRowError = vi.fn();
  const boom = () => {
    throw new Error('boom');
  };
  const { rerender } = render(
    <TicketTable tickets={TICKETS.slice(0, 1)} onRowError={onRowError} renderDetail={boom} />,
  );
  rerender(<TicketTable tickets={TICKETS.slice(0, 1)} onRowError={onRowError} renderDetail={boom} />);
  rerender(<TicketTable tickets={TICKETS.slice(0, 1)} onRowError={onRowError} renderDetail={boom} />);
  expect(onRowError.mock.calls.length).toBe(1);
  expect(onRowError.mock.calls[0][0]).toBe('t1');
});

it('取消分类不算错误且不上报监控', () => {
  const onRowError = vi.fn();
  render(
    <TicketTable
      tickets={TICKETS}
      onRowError={onRowError}
      renderDetail={(row) => {
        if (row.id === 't3') throw abortError();
        return row.raw.title;
      }}
    />,
  );
  expect(screen.getByTestId('row-cancelled-t3').textContent).toBe('本行已取消');
  expect(onRowError).not.toHaveBeenCalled();
  expect(screen.getByTestId('cell-t1').textContent).toBe('退款');
});

it('契约破坏整体抛给外层边界且 reset 后可恢复', () => {
  const onCatch = vi.fn();
  const view = render(
    <TableBoundary onCatch={onCatch}>
      <TicketTable tickets={null} renderDetail={(row) => row.raw.title} />
    </TableBoundary>,
  );
  expect(screen.getByTestId('reset').textContent).toBe('table-failed');
  expect(onCatch.mock.calls.length).toBeGreaterThanOrEqual(1);
  fireEvent.click(screen.getByTestId('reset'));
  expect(screen.getByTestId('reset').textContent).toBe('table-failed');
  view.rerender(
    <TableBoundary onCatch={onCatch}>
      <TicketTable tickets={TICKETS} renderDetail={(row) => row.raw.title} />
    </TableBoundary>,
  );
  fireEvent.click(screen.getByTestId('reset'));
  expect(screen.getByTestId('cell-t2').textContent).toBe('改签');
  expect(screen.getByTestId('summary').textContent).toBe('共 3 行');
});

it('坏行的错误对象原样交给上报回调', () => {
  const onRowError = vi.fn();
  const marker = { status: 422, message: 'amount too large' };
  render(
    <TicketTable
      tickets={TICKETS}
      onRowError={onRowError}
      renderDetail={(row) => {
        if (row.id === 't1') throw marker;
        return row.raw.title;
      }}
    />,
  );
  expect(onRowError.mock.calls.length).toBe(1);
  expect(onRowError.mock.calls[0][1]).toBe(marker);
});

