import { Component } from 'react';
import type { ErrorInfo, ReactNode } from 'react';

export interface Ticket {
  id: string;
  raw: unknown;
}

export interface TicketTableProps {
  tickets: Ticket[] | null | undefined;
  renderDetail: (ticket: Ticket) => ReactNode;
  onRowError?: (ticketId: string, error: unknown) => void;
}

/** 取消不是故障：名字为 AbortError 的抛出走独立 UI，且不进监控上报。 */
function isCancellation(error: unknown): boolean {
  return typeof error === 'object' && error !== null && (error as { name?: unknown }).name === 'AbortError';
}

interface RowBoundaryState {
  failed: boolean;
  cancelled: boolean;
}

/**
 * 边界接不住"自己 render 里"抛的错，只接得住后代组件的。所以脏数据的渲染要放进
 * 一个真正的后代（RowContent），而不是在父级求值好当 children 传进来。
 */
function RowContent({ render }: { render: () => ReactNode }) {
  return <>{render()}</>;
}

/**
 * 每行一个边界：只降级坏行。上报去重靠 reported 标记，避免"每次重渲染都报一次"刷爆监控。
 */
class RowBoundary extends Component<{ ticketId: string; render: () => ReactNode; onRowError?: (id: string, error: unknown) => void }, RowBoundaryState> {
  state: RowBoundaryState = { failed: false, cancelled: false };
  private reported = false;

  static getDerivedStateFromError(error: unknown): RowBoundaryState {
    return { failed: true, cancelled: isCancellation(error) };
  }

  componentDidCatch(error: unknown, _info: ErrorInfo) {
    if (this.reported || isCancellation(error)) return;
    this.reported = true;
    this.props.onRowError?.(this.props.ticketId, error);
  }

  render() {
    if (this.state.cancelled) return <span data-testid={'row-cancelled-' + this.props.ticketId}>本行已取消</span>;
    if (this.state.failed) return <span data-testid={'row-error-' + this.props.ticketId}>本行暂不可用</span>;
    return (
      <span data-testid={'cell-' + this.props.ticketId}>
        <RowContent render={this.props.render} />
      </span>
    );
  }
}

export function TicketTable({ tickets, renderDetail, onRowError }: TicketTableProps): ReactNode {
  // 契约破坏（不是数组）必须显式抛给外层边界，不能渲染半张表骗过用户
  if (!Array.isArray(tickets)) {
    throw new Error('TicketTable 契约破坏：tickets 必须是数组');
  }
  if (tickets.length === 0) return <span data-testid="empty">暂无数据</span>;
  return (
    <table>
      <tbody>
        {tickets.map((ticket) => (
          <tr key={ticket.id}>
            <td>
              <RowBoundary ticketId={ticket.id} onRowError={onRowError} render={() => renderDetail(ticket)} />
            </td>
          </tr>
        ))}
      </tbody>
      <tfoot>
        <tr>
          <td>
            <span data-testid="summary">{'共 ' + tickets.length + ' 行'}</span>
          </td>
        </tr>
      </tfoot>
    </table>
  );
}

