import { Component } from 'react';

class WholeTableBoundary extends Component {
  state = { err: false };
  static getDerivedStateFromError() {
    return { err: true };
  }
  componentDidCatch(error, _info) {
    if (this.props.onRowError) this.props.onRowError('table', error);
  }
  render() {
    if (this.state.err) return <span data-testid="row-error-table">本行暂不可用</span>;
    return this.props.children;
  }
}

export function TicketTable({ tickets, renderDetail, onRowError }) {
  if (!Array.isArray(tickets)) throw new Error('契约破坏');
  return (
    <WholeTableBoundary onRowError={onRowError}>
      <table>
        <tbody>
          {(tickets || []).map((ticket) => (
            <tr key={ticket.id}>
              <td>
                <span data-testid={'cell-' + ticket.id}>{renderDetail(ticket)}</span>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </WholeTableBoundary>
  );
}
